import React from "react";
import { Link } from "react-router-dom";
import { motion } from "framer-motion";
import { Circle, Users, Target, Award, Clock } from "lucide-react";
import {
  HeroSection,
  fadeUpVariants,
  heroBadgeClass,
  heroContainerClass,
  heroHeadingClass,
  heroParagraphClass,
  heroPrimaryButtonClass,
  heroSecondaryButtonClass,
} from "../common/HeroSection";

const AboutHero = () => {
  return (
    <HeroSection>
      <div className={heroContainerClass}>
        <div className="max-w-4xl mx-auto text-center">
          <motion.div
            custom={0}
            variants={fadeUpVariants}
            initial="hidden"
            animate="visible"
            className={`${heroBadgeClass} mb-8`}>
          </motion.div>

          <motion.div
            custom={1}
            variants={fadeUpVariants}
            initial="hidden"
            animate="visible"
          >
            <h1 className={`${heroHeadingClass} mb-6`}>
              <span className="bg-clip-text text-transparent bg-gradient-to-b from-gray-900 to-gray-700">
                About Blitz India
              </span>
              <br />
              <span className="bg-clip-text text-transparent bg-gradient-to-r from-orange-600 via-gray-800 to-gray-600">
                Engineering Excellence
              </span>
            </h1>
          </motion.div>

          {/* Additional info badges */}
          <motion.div
            custom={3}
            variants={fadeUpVariants}
            initial="hidden"
            animate="visible"
            className="flex flex-wrap justify-center gap-4 mb-8"
          >
            {[
              "Explore Our Story",
              "Achieve Excellence",
              "Connect with Us",
            ].map((text) => (
              <div
                key={text}
                className="flex items-center gap-2 px-4 py-2 rounded-full bg-white/80 border border-gray-300 backdrop-blur-sm shadow-sm"
              >
                <Circle className="h-2 w-2 fill-orange-500/80" />
                <span className="text-sm text-gray-700 font-medium">{text}</span>
              </div>
            ))}
          </motion.div>

          {/* CTA Buttons */}
          <motion.div
            custom={5}
            variants={fadeUpVariants}
            initial="hidden"
            animate="visible"
            className="flex flex-col sm:flex-row gap-4 justify-center"
          >
            <Link
              to="/contact"
              className={heroPrimaryButtonClass}
            >
              Start Your Project
            </Link>
          </motion.div>
        </div>
      </div>
    </HeroSection>
  );
};

export default AboutHero;

import React, { useEffect, useState } from 'react';

const defaultSettings = {
  brandName: 'Blitz India Engineering',
  tagline: 'Engineering Excellence Delivered',
  theme: 'light',
  primaryColor: '#EA580C', // orange-600
  contactEmail: 'info@blitzindiaengineering.com',
  contactPhone: '+91-9158575785',
};

const loadSettings = () => {
  try {
    const raw = localStorage.getItem('admin.settings');
    return raw ? JSON.parse(raw) : defaultSettings;
  } catch (e) {
    return defaultSettings;
  }
};

const saveSettings = (settings) => {
  localStorage.setItem('admin.settings', JSON.stringify(settings));
};

const AdminSettings = () => {
  const [settings, setSettings] = useState(defaultSettings);
  const [saved, setSaved] = useState(false);

  useEffect(() => {
    setSettings(loadSettings());
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setSettings((s) => ({ ...s, [name]: value }));
    setSaved(false);
  };

  const handleThemeToggle = (theme) => {
    setSettings((s) => ({ ...s, theme }));
    setSaved(false);
  };

  const handleSave = (e) => {
    e.preventDefault();
    saveSettings(settings);
    setSaved(true);
    setTimeout(() => setSaved(false), 3000);
  };

  return (
    <div className="space-y-8">
      {/* Header */}
      <div>
        <h1 className="text-4xl font-bold bg-gradient-to-r from-orange-600 via-orange-700 to-orange-800 bg-clip-text text-transparent mb-2">
          Settings
        </h1>
        <p className="text-gray-600 text-lg">Manage your site settings and preferences</p>
      </div>

      {saved && (
        <div className="mb-6 p-4 bg-green-50 border border-green-200 text-green-700 rounded-xl shadow-sm">
          <div className="flex items-center">
            <svg className="w-5 h-5 mr-2" fill="currentColor" viewBox="0 0 20 20">
              <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
            </svg>
            Settings saved successfully.
          </div>
        </div>
      )}

      <form onSubmit={handleSave} className="space-y-8">
        {/* Branding */}
        <section className="bg-white p-6 md:p-8 rounded-2xl shadow-lg border border-gray-100">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-gray-900">Branding</h2>
            <div className="w-12 h-1 bg-gradient-to-r from-orange-600 to-orange-700 rounded-full"></div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Brand Name</label>
              <input 
                name="brandName" 
                value={settings.brandName} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Tagline</label>
              <input 
                name="tagline" 
                value={settings.tagline} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
              />
            </div>
          </div>
        </section>

        {/* Theme */}
        <section className="bg-white p-6 md:p-8 rounded-2xl shadow-lg border border-gray-100">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-gray-900">Theme</h2>
            <div className="w-12 h-1 bg-gradient-to-r from-orange-600 to-orange-700 rounded-full"></div>
          </div>
          <div className="flex items-center gap-4">
            <button 
              type="button" 
              onClick={() => handleThemeToggle('light')} 
              className={`px-6 py-3 rounded-xl border-2 font-semibold transition-all ${
                settings.theme === 'light' 
                  ? 'bg-gradient-to-r from-orange-600 to-orange-700 text-white border-orange-600 shadow-lg' 
                  : 'bg-white text-gray-700 border-gray-300 hover:border-gray-400'
              }`}
            >
              Light
            </button>
            <button 
              type="button" 
              onClick={() => handleThemeToggle('dark')} 
              className={`px-6 py-3 rounded-xl border-2 font-semibold transition-all ${
                settings.theme === 'dark' 
                  ? 'bg-gradient-to-r from-orange-600 to-orange-700 text-white border-orange-600 shadow-lg' 
                  : 'bg-white text-gray-700 border-gray-300 hover:border-gray-400'
              }`}
            >
              Dark
            </button>
            <div className="ml-6">
              <label className="block text-sm font-semibold text-gray-700 mb-2">Primary Color</label>
              <div className="flex items-center gap-3">
                <input 
                  type="color" 
                  name="primaryColor" 
                  value={settings.primaryColor} 
                  onChange={handleChange} 
                  className="w-16 h-12 p-1 border-2 border-gray-300 rounded-xl cursor-pointer"
                />
                <span className="text-sm text-gray-600 font-mono">{settings.primaryColor}</span>
              </div>
            </div>
          </div>
        </section>

        {/* Contact Info */}
        <section className="bg-white p-6 md:p-8 rounded-2xl shadow-lg border border-gray-100">
          <div className="flex items-center justify-between mb-6">
            <h2 className="text-2xl font-bold text-gray-900">Contact Information</h2>
            <div className="w-12 h-1 bg-gradient-to-r from-orange-600 to-orange-700 rounded-full"></div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Email</label>
              <input 
                name="contactEmail" 
                type="email"
                value={settings.contactEmail} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Phone</label>
              <input 
                name="contactPhone" 
                type="tel"
                value={settings.contactPhone} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
              />
            </div>
          </div>
        </section>

        <div className="flex justify-end">
          <button 
            type="submit" 
            className="px-8 py-3 bg-gradient-to-r from-orange-600 to-orange-700 text-white font-semibold rounded-xl hover:from-orange-700 hover:to-orange-800 transition-all duration-200 shadow-lg hover:shadow-xl transform hover:scale-105"
          >
            Save Settings
          </button>
        </div>
      </form>
    </div>
  );
};

export default AdminSettings;

import React, { useEffect, useState } from 'react';

const initialForm = {
  title: '',
  category: '',
  date: '',
  excerpt: '',
  image: '',
  content: '',
};

const loadBlogs = () => {
  try {
    const raw = localStorage.getItem('admin.blogs');
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    return [];
  }
};

const saveBlogs = (blogs) => {
  localStorage.setItem('admin.blogs', JSON.stringify(blogs));
};

const BlogsManager = () => {
  const [blogs, setBlogs] = useState([]);
  const [form, setForm] = useState(initialForm);
  const [isEditing, setIsEditing] = useState(null);

  useEffect(() => {
    setBlogs(loadBlogs());
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((f) => ({ ...f, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.title || !form.excerpt) return;
    
    if (isEditing) {
      const next = blogs.map(b => b.id === isEditing ? { ...form, id: isEditing } : b);
      setBlogs(next);
      saveBlogs(next);
      setIsEditing(null);
    } else {
      const newBlog = { id: Date.now(), ...form };
      const next = [newBlog, ...blogs];
      setBlogs(next);
      saveBlogs(next);
    }
    setForm(initialForm);
  };

  const removeBlog = (id) => {
    if (window.confirm('Are you sure you want to delete this blog?')) {
      const next = blogs.filter((b) => b.id !== id);
      setBlogs(next);
      saveBlogs(next);
    }
  };

  const editBlog = (blog) => {
    setForm(blog);
    setIsEditing(blog.id);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cancelEdit = () => {
    setForm(initialForm);
    setIsEditing(null);
  };

  return (
    <div className="space-y-8">
      {/* Header */}
      <div>
        <h1 className="text-4xl font-bold bg-gradient-to-r from-orange-600 via-orange-700 to-orange-800 bg-clip-text text-transparent mb-2">
          Manage Blogs
        </h1>
        <p className="text-gray-600 text-lg">Create and manage your blog posts</p>
      </div>

      {/* Form */}
      <div className="bg-white rounded-2xl shadow-lg p-6 md:p-8 border border-gray-100">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-gray-900">
            {isEditing ? 'Edit Blog' : 'Add New Blog'}
          </h2>
          {isEditing && (
            <button
              onClick={cancelEdit}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
            >
              Cancel
            </button>
          )}
        </div>
        
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Title *</label>
              <input 
                name="title" 
                value={form.title} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="Blog title"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Category</label>
              <input 
                name="category" 
                value={form.category} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="e.g. Manufacturing, Engineering"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Date</label>
              <input 
                name="date" 
                value={form.date} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="Oct 2025"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Image URL</label>
              <input 
                name="image" 
                value={form.image} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="https://example.com/image.jpg"
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Excerpt *</label>
            <textarea 
              name="excerpt" 
              value={form.excerpt} 
              onChange={handleChange} 
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
              rows={3} 
              placeholder="Brief summary of the blog post"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Content</label>
            <textarea 
              name="content" 
              value={form.content} 
              onChange={handleChange} 
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
              rows={6} 
              placeholder="Full blog content"
            />
          </div>
          <div className="flex justify-end">
            <button 
              type="submit" 
              className="px-8 py-3 bg-gradient-to-r from-orange-600 to-orange-700 text-white font-semibold rounded-xl hover:from-orange-700 hover:to-orange-800 transition-all duration-200 shadow-lg hover:shadow-xl transform hover:scale-105"
            >
              {isEditing ? 'Update Blog' : 'Add Blog'}
            </button>
          </div>
        </form>
      </div>

      {/* Blogs Grid */}
      <div>
        <h2 className="text-2xl font-bold text-gray-900 mb-6">All Blogs ({blogs.length})</h2>
        {blogs.length === 0 ? (
          <div className="bg-white rounded-2xl shadow-lg p-12 border border-gray-100 text-center">
            <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
              <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
              </svg>
            </div>
            <p className="text-gray-500 text-lg">No blogs yet. Add your first blog above.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {blogs.map((b) => (
              <article 
                key={b.id} 
                className="bg-white rounded-2xl shadow-lg border border-gray-100 overflow-hidden hover:shadow-xl transition-all duration-300 group"
              >
                {b.image && (
                  <div className="h-48 overflow-hidden">
                    <img 
                      src={b.image} 
                      alt={b.title}
                      className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-300"
                    />
                  </div>
                )}
                <div className="p-6">
                  <div className="flex items-center justify-between mb-3">
                    <span className="text-sm font-semibold text-orange-600 bg-orange-50 px-3 py-1 rounded-full">
                      {b.category || 'General'}
                    </span>
                    <span className="text-xs text-gray-500">{b.date}</span>
                  </div>
                  <h2 className="text-xl font-bold text-gray-900 mb-3 line-clamp-2">{b.title}</h2>
                  <p className="text-base sm:text-lg font-medium text-gray-600 mb-4 line-clamp-3">{b.excerpt}</p>
                  <div className="flex items-center justify-between pt-4 border-t border-gray-100">
                    <button 
                      onClick={() => editBlog(b)}
                      className="text-orange-600 hover:text-orange-700 text-sm font-semibold transition-colors"
                    >
                      Edit
                    </button>
                    <button 
                      onClick={() => removeBlog(b.id)} 
                      className="text-red-600 hover:text-red-700 text-sm font-semibold transition-colors"
                    >
                      Delete
                    </button>
                  </div>
                </div>
              </article>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default BlogsManager;

import React, { useEffect, useState } from 'react';

const emptyProject = {
  title: '',
  shortDescription: '',
  category: '',
  client: '',
  date: '',
  duration: '',
  image: '',
  description: '',
};

const loadProjects = () => {
  try {
    const raw = localStorage.getItem('admin.projects');
    return raw ? JSON.parse(raw) : [];
  } catch (e) {
    return [];
  }
};

const saveProjects = (projects) => {
  localStorage.setItem('admin.projects', JSON.stringify(projects));
};

const ProjectsManager = () => {
  const [projects, setProjects] = useState([]);
  const [form, setForm] = useState(emptyProject);
  const [isEditing, setIsEditing] = useState(null);

  useEffect(() => {
    setProjects(loadProjects());
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((f) => ({ ...f, [name]: value }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!form.title || !form.shortDescription) return;
    
    if (isEditing) {
      const next = projects.map(p => p._id === isEditing ? { ...form, _id: isEditing, results: p.results || [] } : p);
      setProjects(next);
      saveProjects(next);
      setIsEditing(null);
    } else {
      const newProject = { _id: Date.now(), results: [], ...form };
      const next = [newProject, ...projects];
      setProjects(next);
      saveProjects(next);
    }
    setForm(emptyProject);
  };

  const removeProject = (id) => {
    if (window.confirm('Are you sure you want to delete this project?')) {
      const next = projects.filter((p) => p._id !== id);
      setProjects(next);
      saveProjects(next);
    }
  };

  const editProject = (project) => {
    setForm(project);
    setIsEditing(project._id);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const cancelEdit = () => {
    setForm(emptyProject);
    setIsEditing(null);
  };

  return (
    <div className="space-y-8">
      {/* Header */}
      <div>
        <h1 className="text-4xl font-bold bg-gradient-to-r from-orange-600 via-orange-700 to-orange-800 bg-clip-text text-transparent mb-2">
          Manage Projects
        </h1>
        <p className="text-gray-600 text-lg">Create and manage your portfolio projects</p>
      </div>

      {/* Form */}
      <div className="bg-white rounded-2xl shadow-lg p-6 md:p-8 border border-gray-100">
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-gray-900">
            {isEditing ? 'Edit Project' : 'Add New Project'}
          </h2>
          {isEditing && (
            <button
              onClick={cancelEdit}
              className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 rounded-lg hover:bg-gray-200 transition-colors"
            >
              Cancel
            </button>
          )}
        </div>
        
        <form onSubmit={handleSubmit} className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Title *</label>
              <input 
                name="title" 
                value={form.title} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="Project title"
                required
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Category</label>
              <input 
                name="category" 
                value={form.category} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="e.g. Automotive, Aerospace"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Client</label>
              <input 
                name="client" 
                value={form.client} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="Client name"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Date</label>
              <input 
                name="date" 
                value={form.date} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="YYYY-MM-DD"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Duration</label>
              <input 
                name="duration" 
                value={form.duration} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="e.g. 3 months"
              />
            </div>
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Image URL</label>
              <input 
                name="image" 
                value={form.image} 
                onChange={handleChange} 
                className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
                placeholder="https://example.com/image.jpg"
              />
            </div>
          </div>
          <div>
            <label className="block text-sm font-semibold text-gray-700 mb-2">Short Description *</label>
            <input 
              name="shortDescription" 
              value={form.shortDescription} 
              onChange={handleChange} 
              className="w-full px-4 py-3 border border-gray-300 rounded-xl focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition-all"
              placeholder="Brief project description"
              required
            />
          </div>
